// ZOHO CRM — LEAD ROUTING AND STAGE SWEEP — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows ("01 lead routing" and "02 stage sweep").
// build.py regenerates both from this one file and validate.py fails if they drift apart,
// so you never paste it between them by hand.
//
// A blank id or key means that step is SKIPPED, never that the run fails. That is what lets
// this be demonstrated on a screen-share before a single Zoho credential exists.

// ---------------------------------------------------------------- Safety
// DRY_RUN ships true. Nothing is created in Zoho until you change it, deliberately.
const DRY_RUN = true;

// ---------------------------------------------------------------- Which Zoho you are on
// Zoho is regional and the data centre is part of the URL. Getting this wrong is the most
// common reason a working integration returns INVALID_TOKEN against a perfectly valid token.
//   US   https://www.zohoapis.com       accounts: https://accounts.zoho.com
//   EU   https://www.zohoapis.eu        accounts: https://accounts.zoho.eu
//   IN   https://www.zohoapis.in        accounts: https://accounts.zoho.in
//   AU   https://www.zohoapis.com.au    accounts: https://accounts.zoho.com.au
//   JP   https://www.zohoapis.jp        accounts: https://accounts.zoho.jp
//   CA   https://www.zohoapis.ca        accounts: https://accounts.zohocloud.ca
const ZOHO_API_BASE      = 'https://www.zohoapis.com';
const ZOHO_ACCOUNTS_BASE = 'https://accounts.zoho.com';
const ZOHO_API_VERSION   = 'v8';

// ---------------------------------------------------------------- Getting in
// A Zoho access token lives for ONE HOUR. Do not paste one here: it will work in the demo
// and stop working before the first real day is out. Register a Self Client or a
// Server-based app at api-console.zoho.com, authorise it once with the scopes below, and
// keep the REFRESH token. These workflows exchange it for a fresh access token at the top of
// every run, which is the difference between an integration that survives and one that has
// to be re-authorised by hand every morning.
//
// Scopes: ZohoCRM.modules.leads.CREATE, ZohoCRM.modules.deals.READ,
//         ZohoCRM.modules.tasks.CREATE, ZohoCRM.coql.READ
//
// All three blank -> both workflows build the exact request and stop in front of it, so you
// can read what they would have sent. They ship blank: this file goes out as a work sample.
const ZOHO_CLIENT_ID     = '';
const ZOHO_CLIENT_SECRET = '';
const ZOHO_REFRESH_TOKEN = '';

// ---------------------------------------------------------------- Do Zoho's own rules fire?
// Zoho runs workflow rules, approvals and blueprint transitions on a record created over the
// API only when you ask it to. An empty list means none of them fire; ['workflow'] means
// workflow rules do.
//
// Leave this EMPTY while Deluge is still doing the routing, or a lead written here is routed
// twice — once by this workflow and once by the rule that used to do it. Turn it on
// deliberately, one rule at a time, as the old ones are retired.
const ZOHO_TRIGGERS = [];

// ---------------------------------------------------------------- The layout
// Leads and Deals both carry an Owner. A blank owner id means the record is created
// unassigned rather than the run failing.
const LEAD_LAYOUT_ID = '';
const OWNERS = [
  { owner: 'Ada',  user_id: '' },
  { owner: 'Ben',  user_id: '' },
  { owner: 'Cara', user_id: '' }
];

// Zoho field API name -> where to read it off the lead. A blank api_name is skipped rather
// than written as an empty field, so a half-mapped org still writes a clean record.
const CUSTOM_FIELDS = [
  { api_name: 'Lead_Source_Detail', from: 'source'  },
  { api_name: 'Enquiry_Type',       from: 'wants'   },
  { api_name: 'Summary',            from: 'summary' }
];

// ---------------------------------------------------------------- Who gets what
// The rule table. First match wins. A rule may match on the intake source, on what the
// person wants, on both — and the last rule matches nothing on purpose, so a lead that fits
// no rule still lands somewhere rather than nowhere.
//
// THIS TABLE IS THE POINT. When routing changes — a new segment, someone leaves, a status
// gets renamed — it is one row here, not a Deluge function somebody has to open.
const ROUTING_RULES = [
  { match: { wants: 'support' },  owner: 'Cara', status: 'Support',         tags: ['support'] },
  { match: { wants: 'quote' },    owner: 'Ben',  status: 'Quote Requested', tags: ['quote'] },
  { match: { wants: 'demo' },     owner: 'Ben',  status: 'Attempted',       tags: ['demo'] },
  { match: { source: 'phone' },   owner: 'Ben',  status: 'Attempted',       tags: ['phone'] },
  { match: { source: 'email' },   owner: 'Ada',  status: 'Attempted',       tags: ['email'] },
  { match: { source: 'website' }, owner: 'Ada',  status: 'Attempted',       tags: ['website'] },
  { match: {},                    owner: 'Ada',  status: 'Attempted',       tags: ['unrouted'] }
];

// On every lead this workflow writes. The routing rule adds its own.
const BASE_TAGS = ['automation-intake'];

// ---------------------------------------------------------------- The stage sweep
// The rule workflow 02 enforces:
//
//   NO OPEN DEAL SHOULD SIT IN A STAGE WITHOUT THE NEXT ACTION THAT STAGE CALLS FOR.
//
// Zoho's own workflow rules fire on a stage CHANGE. A deal that never moved never fired
// anything, and that is exactly the deal that goes quiet. This runs on a schedule and asks
// every open deal, so the ones nothing fired for are the ones it catches.
const OPEN_STAGES = ['Qualification', 'Needs Analysis', 'Proposal', 'Negotiation'];

// Per stage: the task to create when an open deal has no next action, how soon it is due,
// and how long a deal may sit in that stage before it is called stalled.
const STAGE_ACTIONS = [
  { stage: 'Qualification',  task: 'Qualify: confirm budget, authority and timeline', due_in_days: 2, stale_after_days: 7 },
  { stage: 'Needs Analysis', task: 'Book the scoping call',                           due_in_days: 3, stale_after_days: 10 },
  { stage: 'Proposal',       task: 'Chase the proposal',                              due_in_days: 3, stale_after_days: 14 },
  { stage: 'Negotiation',    task: 'Agree the next step in writing',                  due_in_days: 2, stale_after_days: 10 }
];

// A deal whose next action is ALREADY OVERDUE does not get a second task piled on top of it.
// It is escalated to the digest instead. Stacking tasks is how a pipeline stops being
// trusted, and once nobody trusts it, "nothing falls through the cracks" is over.
const ESCALATE_OVERDUE = true;

// How many deals to read in one run. Anything past this is reported, never silently dropped.
const DEAL_PAGE_LIMIT = 200;

// ---------------------------------------------------------------- Notifications
// Optional. Blank -> nothing is posted and the run still completes. Any endpoint that
// accepts a JSON POST: Slack, Teams, Zoho Cliq, a webhook of your own.
const NOTIFY_WEBHOOK_URL  = '';
const NOTIFY_ON_NEW_LEAD  = true;
const NOTIFY_ON_DIGEST    = true;

// ---------------------------------------------------------------- derived — do not edit
const ZOHO_AUTH_READY = ZOHO_CLIENT_ID.trim() !== '' &&
                        ZOHO_CLIENT_SECRET.trim() !== '' &&
                        ZOHO_REFRESH_TOKEN.trim() !== '';

const SETTINGS = {
    dry_run: DRY_RUN === true,
    zoho_api_base: ZOHO_API_BASE.replace(/\/+$/, ''),
    zoho_accounts_base: ZOHO_ACCOUNTS_BASE.replace(/\/+$/, ''),
    zoho_api_version: ZOHO_API_VERSION,
    zoho_client_id: ZOHO_CLIENT_ID,
    zoho_client_secret: ZOHO_CLIENT_SECRET,
    zoho_refresh_token: ZOHO_REFRESH_TOKEN,
    zoho_triggers: ZOHO_TRIGGERS,
    lead_layout_id: LEAD_LAYOUT_ID,
    owners: OWNERS,
    custom_fields: CUSTOM_FIELDS,
    routing_rules: ROUTING_RULES,
    base_tags: BASE_TAGS,
    open_stages: OPEN_STAGES,
    stage_actions: STAGE_ACTIONS,
    escalate_overdue: ESCALATE_OVERDUE === true,
    deal_page_limit: DEAL_PAGE_LIMIT,
    notify_webhook_url: NOTIFY_WEBHOOK_URL,
    notify_on_new_lead: NOTIFY_ON_NEW_LEAD === true,
    notify_on_digest: NOTIFY_ON_DIGEST === true,
    // derived flags — never test a key's emptiness downstream, test the flag
    zoho_auth_ready: ZOHO_AUTH_READY,
    zoho_enabled: ZOHO_AUTH_READY && DRY_RUN !== true,
    notify_enabled: NOTIFY_WEBHOOK_URL.trim() !== '' && DRY_RUN !== true
};

// config sits IN the data path, so it must not swallow the items passing through it. It runs
// once per incoming item and passes that item's payload along untouched under `lead`, so
// three demo leads in is three leads out — not one settings object.
//
// A trigger that carries no payload (the schedule, the manual run in workflow 02) still
// produces one item, so `$('config').first().json` always resolves.
const incoming = $input.all().length ? $input.all().map((i) => i.json || {}) : [{}];
return incoming.map((lead) => ({ json: Object.assign({}, SETTINGS, { lead: lead }) }));

// Reads the access token out of the refresh-token exchange. The sweep makes one read call,
// so one item is all that is needed here.
//
// Zoho returns HTTP 200 with an `error` key in the body when a refresh fails. A node that
// only checks the status code treats that as success and fails confusingly later with
// INVALID_TOKEN — so the body is checked explicitly, and a bad refresh stops the run here
// with the reason on it.
const res = $input.first().json || {};

if (res.error || !res.access_token) {
  return [{
    json: {
      _authed: false,
      _why: res.error ? 'Zoho refused the refresh: ' + res.error
                      : 'Zoho returned no access_token',
      _hint: res.error === 'invalid_client'
        ? 'client id/secret belong to a different data centre than ZOHO_ACCOUNTS_BASE'
        : res.error === 'invalid_code'
        ? 'the refresh token has been revoked, or was issued for different scopes'
        : 'check ZOHO_ACCOUNTS_BASE matches the region the app was registered in',
      _response: res
    }
  }];
}

return [{
  json: {
    _authed: true,
    _access_token: res.access_token,
    _expires_in: res.expires_in || 3600,
    _obtained_at: new Date().toISOString()
  }
}];

// The refresh-token exchange failed, so nothing downstream ran. This is a named stop rather
// than a swallowed error because an expired refresh token is the most common way a Zoho
// integration dies quietly: every run "succeeds", nothing is ever written, and nobody notices
// until someone asks where the week's leads went.
//
// `_hint` is the thing to read first — it maps Zoho's terse error to the cause.
return $input.all().map((i) => ({
  json: {
    _outcome: 'not authenticated — nothing written',
    _reason: i.json._why || 'Zoho refused the refresh token',
    _hint: i.json._hint || 'check ZOHO_ACCOUNTS_BASE matches the data centre the app was registered in',
    zoho_response: JSON.stringify(i.json._response || i.json).slice(0, 600)
  }
}));

// Builds the COQL query that reads the open deals, from the stage list in config.
//
// It is a node rather than an expression buried in the HTTP body so the query can be read on
// a failed run, and so simulate.js can check it before anything is imported. A COQL syntax
// error is otherwise a 400 with no indication of which stage name broke it.
//
// COQL notes: the field list is Zoho API names, `limit` is capped at 200 per call by Zoho,
// and a stage that does not exist in the org does not error — it just matches nothing, which
// is why OPEN_STAGES is worth checking against the org's own picklist on setup.
const cfg = $('config').first().json;

const stages = (cfg.open_stages || [])
  .map((s) => "'" + String(s).replace(/'/g, "\\'") + "'")
  .join(', ');

const limit = Math.min(Number(cfg.deal_page_limit || 200), 200);

const query = [
  'select id, Deal_Name, Stage, Owner, Amount, Closing_Date, Next_Step, Modified_Time',
  'from Deals',
  stages ? 'where Stage in (' + stages + ')' : "where id is not null",
  'limit ' + limit
].join(' ');

return [{
  json: {
    _authed: true,
    _access_token: $input.first().json._access_token,
    query,
    select_query: query
  }
}];

// Zoho could not be read, so the sweep did not run. It deliberately does NOT fall back to
// the demo pipeline: sweeping invented deals against a real org would create tasks on records
// that do not exist and report a clean pipeline that was never looked at.
//
// A sweep that could not see the pipeline must say so and stop. That is the whole point of
// this node existing rather than an empty result.
return $input.all().map((i) => {
  const j = i.json || {};
  const err = j.error || j;
  const detail = (err && (err.message || err.description || err.error)) || j;
  return {
    json: {
      _outcome: 'sweep did not run',
      _reason: 'Zoho refused the read — no deals were checked and no tasks were created',
      _hint: 'a COQL read needs the ZohoCRM.coql.READ scope as well as deals.READ; ' +
             'a 400 with INVALID_QUERY usually means a stage name in OPEN_STAGES does not ' +
             'exist in this org',
      zoho_response: typeof detail === 'string' ? detail : JSON.stringify(detail).slice(0, 600)
    }
  };
});

// Six invented deals so workflow 02 runs end to end with no Zoho account, and so one run
// shows every verdict the sweep can reach: two needing a task created, one escalated because
// its next step is already overdue, one stalled, one compliant, one in a stage that is not
// open at all.
//
// A read that FAILS does not fall back to these. A fabricated deal must never be swept
// against a real org — see STOP: could not read the pipeline.
function daysAgo(n) {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString();
}
function dateIn(n) {
  const d = new Date();
  d.setDate(d.getDate() + n);
  return d.toISOString().slice(0, 10);
}

return [
  // No next step at all, sitting in Qualification -> a task is created.
  { json: { _demo: true, id: '4100000001', Deal_Name: 'Northgate Clinics — platform rollout',
            Stage: 'Qualification', Owner: { id: '', name: 'Ada' }, Amount: 18000,
            Closing_Date: dateIn(40), Next_Step: '', Modified_Time: daysAgo(3) } },

  // No next step, in Proposal -> a task is created, and it is also stalled.
  { json: { _demo: true, id: '4100000002', Deal_Name: 'Ferris Group — annual licence',
            Stage: 'Proposal', Owner: { id: '', name: 'Ben' }, Amount: 42000,
            Closing_Date: dateIn(12), Next_Step: '', Modified_Time: daysAgo(21) } },

  // Has a next step but the close date has already passed -> escalated, NOT stacked.
  { json: { _demo: true, id: '4100000003', Deal_Name: 'Calder Pharmacy — onboarding',
            Stage: 'Negotiation', Owner: { id: '', name: 'Ben' }, Amount: 9500,
            Closing_Date: dateIn(-6), Next_Step: 'Waiting on their legal review',
            Modified_Time: daysAgo(8) } },

  // Compliant: a next step, and the close date is still ahead.
  { json: { _demo: true, id: '4100000004', Deal_Name: 'Whitlock & Co — pilot',
            Stage: 'Needs Analysis', Owner: { id: '', name: 'Cara' }, Amount: 6000,
            Closing_Date: dateIn(25), Next_Step: 'Scoping call booked for Thursday',
            Modified_Time: daysAgo(1) } },

  // Compliant but untouched for a long time -> reported as stalled, no task created.
  { json: { _demo: true, id: '4100000005', Deal_Name: 'Hale Medical — data migration',
            Stage: 'Qualification', Owner: { id: '', name: 'Ada' }, Amount: 15000,
            Closing_Date: dateIn(60), Next_Step: 'Chasing an intro to their CTO',
            Modified_Time: daysAgo(30) } },

  // Not an open stage -> the sweep leaves it alone entirely.
  { json: { _demo: true, id: '4100000006', Deal_Name: 'Ardent Labs — renewal',
            Stage: 'Closed Won', Owner: { id: '', name: 'Cara' }, Amount: 30000,
            Closing_Date: dateIn(-2), Next_Step: '', Modified_Time: daysAgo(5) } }
];

// Turns whatever arrived — a Zoho COQL response, or the built-in demo pipeline — into one
// flat list of deals. Everything downstream reads the same keys, so the sweep logic is
// identical whether or not a credential exists.
//
// Zoho's COQL answers { data: [...], info: { count, more_records } }. `more_records` is
// reported rather than ignored: a sweep that silently saw only the first page would report
// a clean pipeline while leaving deals unswept, which is worse than not running.
const cfg = $('config').first().json;
const items = $input.all().map((i) => i.json || {});

let rows = [];
let truncated = false;

// One item carrying a COQL envelope, or a list of already-flat demo deals.
if (items.length === 1 && items[0] && Array.isArray(items[0].data)) {
  rows = items[0].data;
  truncated = !!(items[0].info && items[0].info.more_records);
} else {
  rows = items.filter((r) => r && (r.id || r.Deal_Name));
}

const limit = Number(cfg.deal_page_limit || 200);
if (rows.length > limit) {
  truncated = true;
  rows = rows.slice(0, limit);
}

return rows.map((d) => ({
  json: {
    _demo: d._demo === true,
    _truncated: truncated,
    id: String(d.id || ''),
    name: d.Deal_Name || '(unnamed deal)',
    stage: d.Stage || '',
    owner: (d.Owner && (d.Owner.name || d.Owner.id)) || '',
    owner_id: (d.Owner && d.Owner.id) || '',
    amount: Number(d.Amount || 0),
    closing_date: d.Closing_Date || '',
    next_step: String(d.Next_Step || '').trim(),
    modified_time: d.Modified_Time || ''
  }
}));

// THE RULE: no open deal should sit in a stage without the next action that stage calls for.
//
// Zoho's own workflow rules fire on a stage CHANGE. A deal that never moved never fired
// anything — and that is precisely the deal that goes quiet. This asks every open deal,
// every morning, so the ones nothing fired for are the ones it catches. That is the whole
// argument for running this beside Zoho's rules rather than instead of them.
//
// Four verdicts, and only one of them writes anything:
//   create   — open, no next step recorded. The stage's task is created.
//   escalate — open, has a next step, but it is already overdue. Reported, NOT stacked with
//              a second task: piling tasks on a deal is how a pipeline stops being trusted.
//   ok       — open, has a next step, not overdue. Nothing happens.
//   skip     — not in an open stage. The sweep leaves it alone.
//
// `stalled` is orthogonal: a deal can be compliant and still untouched for a month. It is
// reported in the digest and never creates a task on its own.
const cfg = $('config').first().json;
const now = new Date();

const actions = {};
for (const a of cfg.stage_actions || []) actions[a.stage] = a;
const open = cfg.open_stages || [];

function daysBetween(a, b) {
  return Math.floor((a - b) / 86400000);
}

const out = $input.all().map((item) => {
  const d = item.json || {};
  const rule = actions[d.stage] || null;

  if (open.indexOf(d.stage) < 0) {
    return { json: Object.assign({}, d, { verdict: 'skip', why: 'not an open stage' }) };
  }

  const modified = d.modified_time ? new Date(d.modified_time) : null;
  const daysSinceTouch = modified ? daysBetween(now, modified) : null;
  const staleAfter = rule ? Number(rule.stale_after_days || 0) : 0;
  const stalled = staleAfter > 0 && daysSinceTouch !== null && daysSinceTouch > staleAfter;

  const closing = d.closing_date ? new Date(d.closing_date + 'T23:59:59Z') : null;
  const overdue = closing !== null && closing < now;

  let verdict, why;
  if (!d.next_step) {
    verdict = 'create';
    why = 'open deal with no next step recorded';
  } else if (overdue && cfg.escalate_overdue) {
    verdict = 'escalate';
    why = 'next step exists but the close date has passed — escalated, not stacked';
  } else {
    verdict = 'ok';
    why = 'has a next step and is not overdue';
  }

  return {
    json: Object.assign({}, d, {
      verdict,
      why,
      stalled,
      days_since_touch: daysSinceTouch,
      task_title: rule ? rule.task : 'Agree the next step',
      due_in_days: rule ? Number(rule.due_in_days || 2) : 2
    })
  };
});

// One flag the IF node reads, computed once rather than counted in an expression.
const toCreate = out.filter((o) => o.json.verdict === 'create').length;
for (const o of out) {
  o.json._has_work = toCreate > 0;
  o.json._to_create = toCreate;
}
return out;

// Every open deal already has a next step, so nothing was created. This is a named stop
// rather than an empty branch because "the sweep ran and found nothing to do" and "the sweep
// did not run" must never look the same in the execution list.
const deals = $input.all().map((i) => i.json || {});
return [{
  json: {
    _outcome: 'nothing to create',
    _reason: 'every open deal already has a next step recorded',
    open_deals_checked: deals.filter((d) => d.verdict !== 'skip').length,
    escalated: deals.filter((d) => d.verdict === 'escalate').length,
    stalled: deals.filter((d) => d.stalled && d.verdict !== 'skip').length
  }
}];

// Builds the Zoho Task for every deal the sweep judged `create`, as one request, before
// anything is sent — so the exact body can be read on a STOP node when nothing is configured.
//
// Zoho specifics:
//   * POST /crm/v8/Tasks takes { data: [ ... ] }, up to 100 records per call.
//   * Relating a task to a deal needs BOTH What_Id (the deal) and $se_module ('Deals').
//     Sending What_Id alone creates an orphan task that appears nowhere on the deal — the
//     single most common mistake when wiring Zoho tasks over the API.
//   * Due_Date is a date, not a datetime.
const cfg = $('config').first().json;
const base = cfg.zoho_api_base + '/crm/' + cfg.zoho_api_version;

const due = (days) => {
  const d = new Date();
  d.setDate(d.getDate() + Number(days || 2));
  return d.toISOString().slice(0, 10);
};

const create = $input.all()
  .map((i) => i.json || {})
  .filter((d) => d.verdict === 'create');

const records = create.map((d) => {
  const rec = {
    Subject: d.task_title,
    Status: 'Not Started',
    Priority: 'Normal',
    Due_Date: due(d.due_in_days),
    Description: 'Raised by the stage sweep: ' + d.why + '. Deal has been in ' + d.stage +
                 (d.days_since_touch === null ? '' : ' and untouched for ' + d.days_since_touch + ' days') + '.',
    What_Id: d.id,
    $se_module: 'Deals'
  };
  if (d.owner_id) rec.Owner = { id: d.owner_id };
  return rec;
});

// One item carrying the whole batch — Zoho takes up to 100 records in a single call, and one
// call is both faster and easier to read in an execution than N of them.
return [{
  json: {
    _count: records.length,
    _deals: create.map((d) => ({ id: d.id, name: d.name, stage: d.stage, owner: d.owner })),
    _zoho: { url: base + '/Tasks', body: { data: records } }
  }
}];

// Nothing was created in Zoho — DRY_RUN is still true, or the OAuth values are blank. This
// node's output IS the result: the exact Tasks request that would have been sent, and which
// deals it covers.
//
// Open this one on a screen-share. It shows real deals, judged by a real rule, producing a
// real Zoho payload, with nothing written.
const cfg = $('config').first().json;
return $input.all().map((i) => ({
  json: {
    _outcome: 'preview — no tasks created',
    _reason: cfg.dry_run
      ? 'DRY_RUN is true — set it to false in config once the OAuth values are filled in'
      : 'ZOHO_CLIENT_ID / ZOHO_CLIENT_SECRET / ZOHO_REFRESH_TOKEN is blank',
    tasks: i.json._count,
    deals: i.json._deals,
    would_post_to: i.json._zoho ? i.json._zoho.url : null,
    would_post: i.json._zoho ? i.json._zoho.body : null
  }
}));

// Tasks created. As with any Zoho bulk write, a 200 on the request does not mean every
// record was accepted — each result carries its own code, so they are read individually and
// anything that is not SUCCESS is counted as a failure even though the call succeeded.
return $input.all().map((i) => {
  const j = i.json || {};
  const results = (j.data && Array.isArray(j.data)) ? j.data : [];
  const ok = results.filter((r) => String(r.code || '').toUpperCase() === 'SUCCESS');
  const bad = results.filter((r) => String(r.code || '').toUpperCase() !== 'SUCCESS');

  return {
    json: {
      _outcome: bad.length ? 'created with rejections' : 'tasks created',
      _reason: bad.length
        ? bad.length + ' of ' + results.length + ' task(s) were rejected by Zoho'
        : results.length + ' task(s) created',
      created: ok.length,
      rejected: bad.length,
      ids: ok.map((r) => (r.details && r.details.id) || ''),
      rejections: bad.map((r) => ({ code: r.code, message: r.message }))
    }
  };
});

// Zoho refused the Tasks write outright. Visible, with the response on it, rather than a
// sweep that reported work it never did.
//
// The one that actually happens: INVALID_DATA on What_Id, which means the deal id was sent
// without $se_module — the task then has nothing to attach to. compose-the-next-action always
// sends both; if this fires, check the module name has not been renamed in the org.
return $input.all().map((i) => {
  const j = i.json || {};
  const err = j.error || j;
  const detail = (err && (err.message || err.description || err.error)) || j;
  return {
    json: {
      _outcome: 'task creation failed',
      _reason: 'Zoho rejected the Tasks write — no next actions were created this run',
      zoho_response: typeof detail === 'string' ? detail : JSON.stringify(detail).slice(0, 600)
    }
  };
});

// The weekly-shaped summary of one sweep: what was created, what was escalated, what is
// stalled, and what the run could not see.
//
// A report that only lists successes is how a pipeline gets trusted while quietly rotting.
// The counts that matter here are the ones nobody wants: escalated and stalled.
const cfg = $('config').first().json;
const deals = $('check every deal').all().map((i) => i.json || {});

const by = (v) => deals.filter((d) => d.verdict === v);
const stalled = deals.filter((d) => d.stalled && d.verdict !== 'skip');
const truncated = deals.some((d) => d._truncated);

const line = (d) => '• ' + d.name + ' — ' + d.stage + ' (' + (d.owner || 'unassigned') + ')';

const text = [
  'Pipeline sweep — ' + new Date().toISOString().slice(0, 10),
  '',
  'Open deals checked: ' + deals.filter((d) => d.verdict !== 'skip').length,
  'Next action created: ' + by('create').length,
  'Escalated (overdue, not stacked): ' + by('escalate').length,
  'Already compliant: ' + by('ok').length,
  'Stalled: ' + stalled.length,
  ''
];

if (by('escalate').length) {
  text.push('Overdue — these need a person, not a task:');
  by('escalate').forEach((d) => text.push(line(d) + ' — ' + d.next_step));
  text.push('');
}
if (stalled.length) {
  text.push('Untouched too long for their stage:');
  stalled.forEach((d) => text.push(line(d) + ' — ' + d.days_since_touch + ' days'));
  text.push('');
}
if (truncated) {
  text.push('NOTE: more deals matched than DEAL_PAGE_LIMIT allows. Some were not swept.');
  text.push('');
}
if (deals.some((d) => d._demo)) {
  text.push('NOTE: this ran on the built-in demo pipeline. No Zoho account was read.');
}

return [{
  json: {
    _outcome: 'digest composed',
    created: by('create').length,
    escalated: by('escalate').length,
    compliant: by('ok').length,
    stalled: stalled.length,
    truncated,
    _send: cfg.notify_enabled && cfg.notify_on_digest,
    text: text.join('\n'),
    _notify: {
      url: cfg.notify_webhook_url,
      body: { text: text.join('\n') }
    }
  }
}];

// No notification was posted — NOTIFY_WEBHOOK_URL is blank, DRY_RUN is still true, or the
// relevant NOTIFY_ON_* switch is off. The message that would have been sent is on this node,
// so the wording can be agreed before anybody wires a Slack webhook.
const cfg = $('config').first().json;
return $input.all().map((i) => ({
  json: {
    _outcome: 'notification not sent',
    _reason: cfg.notify_webhook_url.trim() === ''
      ? 'NOTIFY_WEBHOOK_URL is blank — nothing to post to'
      : cfg.dry_run
      ? 'DRY_RUN is true'
      : 'the NOTIFY_ON_ switch for this workflow is off',
    would_post_to: i.json._notify ? i.json._notify.url : null,
    would_say: i.json.text || ''
  }
}));

// The notification was accepted by the endpoint. Recorded as its own step so an execution
// shows plainly whether the team was told, separately from whether Zoho was written.
return [{
  json: {
    _outcome: 'team notified',
    _reason: 'the notification endpoint accepted the post'
  }
}];

// The notification endpoint refused the post. Named, with the response on it, because a
// silently dropped notification is indistinguishable from "there was nothing to tell you" —
// and those two need to look different in the execution list.
//
// Note what this node does NOT do: it does not fail the run. Zoho has already been written
// by this point, and losing a Slack message is not a reason to lose the lead.
return $input.all().map((i) => {
  const j = i.json || {};
  const err = j.error || j;
  const detail = (err && (err.message || err.description || err.error)) || j;
  return {
    json: {
      _outcome: 'notification failed',
      _reason: 'the notification endpoint refused the post — the CRM write is unaffected',
      response: typeof detail === 'string' ? detail : JSON.stringify(detail).slice(0, 400)
    }
  };
});
